from pathlib import Path
import json,re,html,csv
root=Path(__file__).resolve().parent
raw=root.joinpath('lessons-source.txt').read_text().splitlines()
lessons=[]
for week,row in enumerate(raw,1):
 title,body,example,lab,questions,key=row.split('|||')
 block='Foundations and safety' if week<=12 else 'Productivity and communication' if week<=20 else 'Data and programming' if week<=28 else 'Machine learning' if week<=36 else 'Generative AI systems' if week<=44 else 'Sector practice' if week<=48 else 'Capstone and portfolio'
 lessons.append(dict(id=f'ai-year1-week-{week:02}',week=week,module_title=block,title=title,status='draft',teacher_review_status='pending',reviewer_id=None,reviewed_at=None,language='en',estimated_minutes=240,objectives=[f'Explain {title.lower()} using the worked example.','Complete the practical task and justify a safety or quality check.'],lesson_text=body,worked_example=example,practical_task=lab,assessment_questions=questions,teacher_answer_guide=key,evidence_required='Completed task, source/assistance log, a failure or correction, and an independent oral explanation.',sessions=[{'minutes':60,'activity':'Read the lesson, discuss the example and answer the first checkpoint without AI.'},{'minutes':60,'activity':'Complete the practical task using fictional data. Paper work is acceptable.'},{'minutes':60,'activity':'Peer-check the artifact, verify sources, identify a failure and revise.'},{'minutes':60,'activity':'Teacher-led assessment, correction and short oral explanation.'}],prerequisite_week=week-1 if week>1 else None))
assert len(lessons)==52 and len({x['title'] for x in lessons})==52
root.joinpath('curriculum-draft.json').write_text(json.dumps({'schema_version':1,'title':'MELA AI Education — Year One','status':'draft','audience':'Secondary-age learners, TVET, university and adult beginners; teacher adaptation required. Not a ready-made grades 1–12 curriculum.','hours':208,'weeks':52,'language':'English; translation and native-language review pending','lessons':lessons},ensure_ascii=False,indent=2)+'\n')
source=root.parent.parent.joinpath('supabase/recovery/history/20260809152923_seed_mela_course_catalog.sql').read_text()
courses=re.findall(r"^\('([^']+)','([^']+)'",source,re.M)
briefs='''Write a bounded AI use-case safety brief|Create a one-hour introductory activity and misconception check|Compare two beginner chat workflows with a factual-error log|Evaluate a second provider using the same six fictional tasks|Compare conversational outputs without assuming provider accuracy|Build a prompt experiment with a fixed evaluation rubric|Produce an accessible fictional policy document|Build a fictional shop spreadsheet with independent formula checks|Create five slides with a truthful chart and source notes|Draft a fictional communication pack with commitment checks|Create a verified vacancy research workflow using sample postings|Produce an evidence-backed fictional CV and interview rubric|Design a study workflow preserving independent student reasoning|Build a source-evidence log with supported and unsupported claims|Create a differentiated lesson with a teacher-checked question key|Write a fictional venture problem brief and assumptions register|Build a policy-grounded FAQ with escalation cases|Draft an original campaign with rights and factual-claim checks|Produce an original poster with a visual defect checklist|Prepare a consent-safe storyboard with captions and asset provenance|Build a privacy, scam and prompt-injection response checklist|Document a repeatable workflow with measured time and error results|Compare prompt versions on ordinary and adversarial fictional cases|Write a reproducible literature-screening protocol and evidence limits|Create an original content portfolio with assistance disclosure|Design a fictional campaign experiment without deceptive targeting|Draft a transparent sales proposal with no fabricated testimonials|Build a customer support prototype with no autonomous refunds|Draft generic onboarding guidance without ranking real candidates|Summarize fictional financial tables with no investment advice|Clean and visualize a fictional dataset with a reproducible log|Design a reminder state machine with duplicate and timeout handling|Write a bounded mock service brief without guaranteed-income claims|Prototype a fictional service and document acceptance criteria|Implement and test a small fictional data-validation program|Evaluate a simple predictive baseline and a model on held-out data|Design a least-privilege AI service with documented failure states|Build a source-grounded FAQ with refusal and injection tests|Produce a model report with split, metrics and release limits|Create a repeatable analysis pipeline with a peer reproduction test|Design a tool workflow with idempotency and human confirmation|Write a product brief with measurable acceptance and a stop rule|Test a fictional business assumption without recruiting customers|Build an educational banking FAQ using fictional policy, never credit decisions|Classify fictional support tickets without intercepting communications|Organize fictional crop observations without chemical recommendations|Format synthetic health information without diagnosis or treatment|Build teacher-reviewed practice with an offline alternative|Draft a fictional public-service FAQ without benefit eligibility decisions|Prepare an anonymized fictional project report without beneficiary targeting|Create a fictional guest guide without real booking actions|Analyze fictional inventory with clear stock and unit definitions|Map a fictional logistics process with a human safety stop'''.split('|')
assert len(courses)==len(briefs)==53
pathways=[]
for (slug,title),brief in zip(courses,briefs):
 weeks=list(range(1,13))+list(range(45,53))
 if any(x in slug for x in ['python','machine-learning','engineer','data']): weeks=list(range(1,13))+list(range(21,53))
 elif any(x in slug for x in ['prompt','automation','research']): weeks=list(range(1,13))+list(range(29,45))+list(range(49,53))
 else: weeks=list(range(1,21))+list(range(45,53))
 pathways.append({'course_slug':slug,'catalogue_title':title,'shared_core_weeks':weeks,'project_brief':brief,'status':'draft','domain_reviewer_required':True,'publication_approved':False})
root.joinpath('catalogue-53-pathway-briefs.json').write_text(json.dumps(pathways,ensure_ascii=False,indent=2)+'\n')
intro='''# MELA AI Education — Year One\n\nDRAFT FOR HUMAN TEACHER REVIEW — 11 October 2026\n\n52 weekly units · 4 guided hours per week · 208 hours total. Each week contains an explanation, worked example, practical task, two checkpoint questions and four session activities. Weeks 12, 28, 36, 48 and 52 are major checkpoints. This is a common foundation with 53 catalogue-linked project briefs, not 53 independently completed year-long qualifications. Existing courses have not been overwritten or marked published.\n\nDesigned for secondary-age learners, TVET, university and adult beginners. Teachers must adapt language, prerequisites, difficulty and safeguarding. Younger learners need separate age-appropriate design. No paid AI account is required: teachers may supply fictional outputs and use paper tracing. Programming can be traced on paper when a computer is unavailable. The pace is a suggested teaching plan, not a claim that reading alone takes 208 hours.\n\nAll examples and tasks are original drafts using fictional data. No lesson or question has been approved by a human teacher. All reviewer fields remain empty. English is the draft language; the five platform-language editions require translation and native-speaker review.\n\nEach week: 60 minutes guided explanation; 60 minutes practical work; 60 minutes peer verification and revision; 60 minutes teacher assessment and correction. Carry incomplete work forward rather than recording completion automatically.\n\n## Assessment and publication gate\n\nTeacher scores each artifact out of 20: conceptual correctness 0–4; practical execution 0–4; evidence and verification 0–4; privacy/safety/rights 0–4; independent explanation 0–4. Proposed progression threshold: 14/20 with no unresolved critical safety or factual error. Teachers must calibrate this proposal locally before adopting it. A critical safety failure blocks publication regardless of total. Retest after correction and retain both attempts.\n\nBefore publication, a verified subject teacher independently solves both checkpoint questions and completes the practical exercise. Check key correctness, acceptable variants, grade fit, source rights, cultural/language fairness and accessibility. Record reviewer identity, date, content version/hash, evidence, decision and corrections. A second reviewer checks disputed or high-stakes content. Automated checking cannot supply teacher sign-off.\n\n## Reading and implementation references\n\nThese primary references are for further checking, not copied course content or endorsements of MELA. Tool interfaces and eligibility can change.\n- Google ML learning index: https://developers.google.com/machine-learning/crash-course/\n- Python tutorial: https://docs.python.org/3/tutorial/\n- NIST AI risk framework: https://www.nist.gov/itl/ai-risk-management-framework\n- MIT course materials: https://ocw.mit.edu/pages/get-started/\n- OpenLearn catalogue: https://www.open.edu/openlearn/free-courses/full-catalogue\n\n'''
handbook=intro
teacher='# MELA Year One — Teacher Answer and Review Guide\n\nDRAFT. These are proposed expected answers, not teacher-approved keys. They are unrelated to the private live MELA question bank. Keep assessment evidence and actual student data in authorized school systems.\n\n'
for x in lessons:
 handbook+=f"## Week {x['week']:02} — {x['title']}\n\nModule: {x['module_title']} · 240 guided minutes · Draft\n\n"+x['lesson_text']+'\n\n### Worked example\n\n'+x['worked_example']+'\n\n### Practical activity\n\n'+x['practical_task']+'\n\n### Check your understanding\n\n'+x['assessment_questions']+'\n\n### Evidence to submit\n\n'+x['evidence_required']+'\n\n'
 teacher+=f"## Week {x['week']:02} — {x['title']}\n\nQuestions: {x['assessment_questions']}\n\nProposed key: {x['teacher_answer_guide']}\n\nReview the practical artifact using the 20-point rubric. Accept equivalent correct reasoning. Ask the learner to explain one decision without AI. Reviewer: __________ Date: __________ Version: __________ Decision: pending / approve / changes required / blocked. Evidence and corrections: __________\n\n"
handbook+='## Catalogue-linked project briefs\n\nChoose a brief suited to the learner’s prior knowledge. These briefs do not certify professional competence or replace domain review.\n\n'
for x in pathways: handbook+=f"### {x['catalogue_title']}\n\n{x['project_brief']}. Use fictional data, provide a baseline, define five acceptance checks, include a failed case and correction, and obtain the appropriate human review.\n\n"
root.joinpath('STUDENT-HANDBOOK.md').write_text(handbook)
root.joinpath('TEACHER-GUIDE.md').write_text(intro+teacher)
# Accessible phone-readable static handbook; escaped text, no scripts or remote assets.
def render_md(text):
 out=[]
 for line in text.splitlines():
  if line.startswith('### '): out.append('<h3>'+html.escape(line[4:])+'</h3>')
  elif line.startswith('## '): out.append('<h2>'+html.escape(line[3:])+'</h2>')
  elif line.startswith('# '): out.append('<h1>'+html.escape(line[2:])+'</h1>')
  elif line: out.append('<p>'+html.escape(line)+'</p>')
 return '\n'.join(out)
style='body{font:18px/1.65 system-ui,sans-serif;max-width:850px;margin:auto;padding:24px;background:#faf8f3;color:#142136}h1,h2,h3{line-height:1.25}h2{border-top:2px solid #d8b45a;padding-top:24px;margin-top:48px}p{overflow-wrap:anywhere}@media print{h2{break-before:page}body{font-size:11pt}}'
root.joinpath('AI-YEAR-ONE.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MELA AI Year One — Teacher Review Draft</title><style>'+style+'</style><main>'+render_md(handbook)+'</main></html>')
root.joinpath('README.md').write_text(intro+'''## Files\n\nAI-YEAR-ONE.html: readable on a phone or printable. STUDENT-HANDBOOK.md: source manuscript. TEACHER-GUIDE.md: proposed answers and sign-off forms. curriculum-draft.json: structured import material with all review fields unset. catalogue-53-pathway-briefs.json: mapping to the existing 53 catalogue slugs. build-package.py and lessons-source.txt: reproducible authorship sources.\n\nDo not bulk-publish the JSON. Import only as drafts, preserve lesson IDs and versions, assign qualified reviewers, and publish only approved versions through the existing admin controls. Do not assign real course IDs or claim credits without authorized mapping.\n''')
print(json.dumps({'weeks':len(lessons),'guided_hours':sum(x['estimated_minutes'] for x in lessons)/60,'catalogue_briefs':len(pathways),'questions':len(lessons)*2,'human_approvals':0,'manuscript_words':len(handbook.split())}))
